#!/usr/bin/env python3
"""
Adds the "PS Dashboard" tab (first tab) to OpsHub.
Run from inside the opshub/ folder of bidgely/ps-automation:

    cd ps-automation/opshub
    python3 add_ps_dashboard.py

It creates ps_dashboard.py and edits server.py, index.html and secret.template.yaml.
Safe to re-run (it skips anything already applied). Review with `git diff` afterwards.
"""
import re, sys, pathlib

ROOT = pathlib.Path('.')
for need in ('server.py', 'index.html'):
    if not (ROOT / need).exists():
        sys.exit('Run this inside the opshub/ folder (server.py / index.html not found).')

PS_DASHBOARD_PY = '"""\nPS Daily Operations Dashboard — Jira data source for the OpsHub "PS Dashboard" tab.\n\nRuns the Jira filters behind the original dashboard\n(https://bidgely.atlassian.net/jira/dashboards/21793) and returns tickets + counts\nas JSON. server.py exposes it at GET /api/ps-dashboard.\n\nConfig (env vars — add to the `opshub-secrets` Kubernetes secret, which the\ndeployment already loads with envFrom):\n    JIRA_EMAIL   - Atlassian account email the API token belongs to\n                   (ideally a shared/service account that can see all the filters)\n    JIRA_TOKEN   - Atlassian API token for that account\n    JIRA_SITE    - OPTIONAL, defaults to https://bidgely.atlassian.net\n\nResults are cached for CACHE_TTL seconds and shared by every viewer, so any number\nof open dashboards costs at most one round of Jira calls per CACHE_TTL.\n"""\n\nimport os\nimport time\nimport logging\nimport threading\nfrom concurrent.futures import ThreadPoolExecutor\n\nimport requests\n\nlog = logging.getLogger(__name__)\n\nJIRA_SITE = os.environ.get(\'JIRA_SITE\', \'https://bidgely.atlassian.net\').rstrip(\'/\')\nCACHE_TTL = 30             # seconds a result is reused for everyone\nMIN_FORCE_SECONDS = 5      # "Refresh now" can\'t hit Jira more often than this\nPAGE_SIZE = 100\nMAX_ISSUES = 500           # per filter; the count stays exact beyond this\nHTTP_TIMEOUT = 25\nFIELDS = [\'summary\', \'priority\', \'status\', \'assignee\', \'created\']\n\n# section -> order on the page. Filter ids are the saved Jira filters used by the\n# original dashboard.\nFILTERS = [\n    # ── Action needed ──\n    {\'id\': 34518, \'name\': \'Unassigned\',           \'section\': \'action\'},\n    {\'id\': 46986, \'name\': \'Action – Blocker\',     \'section\': \'action\'},\n    {\'id\': 46987, \'name\': \'Action – Critical\',    \'section\': \'action\'},\n    {\'id\': 46988, \'name\': \'Action – Normal\',      \'section\': \'action\'},\n    {\'id\': 46990, \'name\': \'BII – Open\',           \'section\': \'action\'},\n    {\'id\': 46984, \'name\': \'Created in last 24h\',  \'section\': \'action\'},\n    {\'id\': 47001, \'name\': \'Aging queue (all action)\', \'section\': \'action\'},\n    # ── Pending on others ──\n    {\'id\': 46991, \'name\': \'Pending – Blocker\',    \'section\': \'pending\'},\n    {\'id\': 46992, \'name\': \'Pending – Critical\',   \'section\': \'pending\'},\n    {\'id\': 46993, \'name\': \'Pending – Normal\',     \'section\': \'pending\'},\n    {\'id\': 46994, \'name\': \'BII – Pending\',        \'section\': \'pending\'},\n    # ── Monitoring ──\n    {\'id\': 45225, \'name\': \'Queue stuck\',          \'section\': \'monitoring\'},\n    {\'id\': 40966, \'name\': \'Ingestion gap\',        \'section\': \'monitoring\'},\n    {\'id\': 46982, \'name\': \'HER\',                  \'section\': \'monitoring\'},\n    {\'id\': 46983, \'name\': \'BRE\',                  \'section\': \'monitoring\'},\n    {\'id\': 45357, \'name\': \'NISC onboarding\',      \'section\': \'monitoring\'},\n    {\'id\': 41065, \'name\': \'Missing files\',        \'section\': \'monitoring\'},\n]\n\n\nclass NotConfigured(Exception):\n    """JIRA_EMAIL / JIRA_TOKEN are not set."""\n\n\n_cache = {\'data\': None, \'at\': 0.0}\n_lock = threading.Lock()\n\n\ndef _auth():\n    email = os.environ.get(\'JIRA_EMAIL\', \'\').strip()\n    token = os.environ.get(\'JIRA_TOKEN\', \'\').strip()\n    if not email or not token:\n        raise NotConfigured(\'JIRA_EMAIL / JIRA_TOKEN are not set on the server\')\n    return (email, token)\n\n\ndef _post(path, body, auth):\n    r = requests.post(\n        JIRA_SITE + path, json=body, auth=auth, timeout=HTTP_TIMEOUT,\n        headers={\'Accept\': \'application/json\'},\n    )\n    r.raise_for_status()\n    return r.json()\n\n\ndef _row(issue):\n    f = issue.get(\'fields\') or {}\n    return {\n        \'key\': issue.get(\'key\'),\n        \'summary\': f.get(\'summary\') or \'\',\n        \'priority\': (f.get(\'priority\') or {}).get(\'name\') or \'\',\n        \'status\': (f.get(\'status\') or {}).get(\'name\') or \'\',\n        \'assignee\': (f.get(\'assignee\') or {}).get(\'displayName\') or \'Unassigned\',\n        \'created\': f.get(\'created\'),\n    }\n\n\ndef _fetch_filter(flt, auth):\n    jql = \'filter = %d\' % flt[\'id\']\n    out = {\'id\': flt[\'id\'], \'name\': flt[\'name\'], \'section\': flt[\'section\'],\n           \'count\': 0, \'issues\': [], \'error\': None, \'truncated\': False}\n    try:\n        issues, token, last = [], None, False\n        while len(issues) < MAX_ISSUES:\n            body = {\'jql\': jql, \'fields\': FIELDS, \'maxResults\': PAGE_SIZE}\n            if token:\n                body[\'nextPageToken\'] = token\n            j = _post(\'/rest/api/3/search/jql\', body, auth)\n            issues.extend(_row(i) for i in j.get(\'issues\', []))\n            token = j.get(\'nextPageToken\')\n            last = bool(j.get(\'isLast\')) or not token\n            if last:\n                break\n        out[\'issues\'] = issues\n        out[\'count\'] = len(issues)\n        if not last:\n            # More tickets than we pull rows for: keep the headline number exact.\n            out[\'truncated\'] = True\n            try:\n                out[\'count\'] = int(_post(\'/rest/api/3/search/approximate-count\', {\'jql\': jql}, auth).get(\'count\', len(issues)))\n            except Exception:\n                log.warning(\'Jira count failed for filter %s\', flt[\'id\'])\n    except Exception as e:\n        # Never leak the token/URL: log the detail, show only a short reason.\n        log.warning(\'PS dashboard: filter %s failed: %s\', flt[\'id\'], e)\n        resp = getattr(e, \'response\', None)\n        out[\'error\'] = \'Jira returned %s\' % resp.status_code if resp is not None else \'Could not reach Jira\'\n    return out\n\n\ndef _fetch_all():\n    auth = _auth()\n    with ThreadPoolExecutor(max_workers=6) as ex:\n        results = list(ex.map(lambda f: _fetch_filter(f, auth), FILTERS))\n    if all(r[\'error\'] for r in results):\n        raise RuntimeError(results[0][\'error\'])\n    return {\'site\': JIRA_SITE, \'updated\': int(time.time() * 1000), \'filters\': results}\n\n\ndef get_data(force=False):\n    """Cached dashboard data. Everyone shares one fetch per CACHE_TTL seconds."""\n    ttl = MIN_FORCE_SECONDS if force else CACHE_TTL\n\n    def fresh():\n        return _cache[\'data\'] is not None and (time.time() - _cache[\'at\']) < ttl\n\n    if fresh():\n        return _cache[\'data\']\n    with _lock:\n        if fresh():\n            return _cache[\'data\']\n        data = _fetch_all()\n        _cache[\'data\'], _cache[\'at\'] = data, time.time()\n        return data\n'
PSD_CSS = "  /* ─── PS DASHBOARD TAB ─────────────────────────────────────── */\n  .psd-bar { display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin-bottom:14px; }\n  .psd-bar .psd-spacer { flex:1; }\n  .psd-updated { font-family:var(--mono); font-size:11px; color:var(--muted); }\n  .psd-chk { display:inline-flex; align-items:center; gap:6px; font-size:12px; color:var(--muted); cursor:pointer; }\n  .psd-chk input { accent-color:var(--accent); }\n  .psd-banner { display:none; padding:10px 14px; margin-bottom:14px; border-radius:6px; font-size:12px;\n    background:rgba(245,82,82,0.08); border:1px solid rgba(245,82,82,0.3); color:var(--danger); }\n  .psd-major { margin-bottom:12px; background:var(--surface); border:1px solid var(--border); border-radius:10px; }\n  .psd-major > summary { list-style:none; cursor:pointer; padding:11px 16px; display:flex; align-items:center; gap:10px;\n    font-family:var(--mono); font-size:12px; letter-spacing:0.08em; text-transform:uppercase; color:var(--accent); }\n  .psd-major > summary::-webkit-details-marker { display:none; }\n  .psd-major > summary::before { content:'▸'; transition:transform .15s; color:var(--muted); }\n  .psd-major[open] > summary::before { transform:rotate(90deg); }\n  .psd-major .psd-total { color:var(--muted); font-size:11px; letter-spacing:0; text-transform:none; }\n  .psd-body { padding:0 14px 14px; }\n  .psd-tiles { display:grid; grid-template-columns:repeat(auto-fill,minmax(150px,1fr)); gap:8px; margin-bottom:12px; }\n  .psd-tile { display:block; text-decoration:none; padding:9px 12px; border-radius:8px; background:var(--surface2);\n    border:1px solid var(--border); color:var(--text); transition:border-color .15s; }\n  .psd-tile:hover { border-color:var(--accent); }\n  .psd-tile .n { font-family:var(--mono); font-size:22px; font-weight:500; line-height:1.1; }\n  .psd-tile .l { font-size:11px; color:var(--muted); margin-top:2px; }\n  .psd-tile.red   .n { color:var(--danger); }\n  .psd-tile.amber .n { color:var(--warn); }\n  .psd-tile.ok    .n { color:var(--success); }\n  .psd-tile.err   .n { color:var(--muted); }\n  .psd-cols { column-width:600px; column-gap:12px; }\n  .psd-sec { break-inside:avoid; margin-bottom:10px; border:1px solid var(--border); border-radius:8px; background:var(--bg); }\n  .psd-sec.wide { column-span:all; }\n  .psd-sec > summary { list-style:none; cursor:pointer; padding:8px 12px; display:flex; align-items:center; gap:8px; font-size:12px; font-weight:500; }\n  .psd-sec > summary::-webkit-details-marker { display:none; }\n  .psd-sec > summary::before { content:'▸'; font-size:10px; color:var(--muted); transition:transform .15s; }\n  .psd-sec[open] > summary::before { transform:rotate(90deg); }\n  .psd-pill { margin-left:auto; font-family:var(--mono); font-size:11px; padding:1px 8px; border-radius:10px;\n    background:var(--surface2); border:1px solid var(--border2); color:var(--text); }\n  .psd-pill a { color:inherit; text-decoration:none; }\n  .psd-scroll { overflow-x:auto; border-top:1px solid var(--border); }\n  .psd-t { width:100%; border-collapse:collapse; font-size:11.5px; }\n  .psd-t th { text-align:left; padding:6px 10px; color:var(--muted); font-weight:500; font-family:var(--mono); font-size:10px;\n    letter-spacing:0.06em; text-transform:uppercase; white-space:nowrap; position:sticky; top:0; background:var(--bg); }\n  .psd-t td { padding:5px 10px; border-top:1px solid var(--border); vertical-align:top; }\n  .psd-t td.s { min-width:200px; } .psd-t td.n { white-space:nowrap; }\n  .psd-t td.m { font-family:var(--mono); white-space:nowrap; }\n  .psd-t a { color:var(--accent); text-decoration:none; }\n  .psd-t a:hover { text-decoration:underline; }\n  .psd-t tr:hover td { background:rgba(79,124,255,0.05); }\n  .psd-pr { font-family:var(--mono); font-size:10px; padding:1px 6px; border-radius:4px; border:1px solid var(--border2); color:var(--muted); }\n  .psd-pr.red   { color:var(--danger); border-color:rgba(245,82,82,0.4); }\n  .psd-pr.amber { color:var(--warn);   border-color:rgba(245,166,35,0.4); }\n  .psd-age.old  { color:var(--danger); }\n  .psd-age.mid  { color:var(--warn); }\n  .psd-empty { padding:10px 12px; font-size:12px; color:var(--muted); border-top:1px solid var(--border); }\n  .psd-more  { padding:8px 12px; font-size:11px; color:var(--muted); border-top:1px solid var(--border); }\n  .psd-more a { color:var(--accent); }\n  .psd-bar-cell { width:90px; }\n  .psd-mini { height:6px; border-radius:3px; background:var(--accent); min-width:2px; }\n"
PSD_NAV = '  <div class="nav-tab" data-tab="psdash" onclick="switchTab(\'psdash\')" title="Live Jira view of PS daily operations">\n    <span class="tab-icon">▦</span> PS Daily Operations Dashboard\n  </div>\n'
PSD_PAGE = '  <!-- ═══════════════════════ PS DASHBOARD TAB ═══════════════════════ -->\n  <div class="page" id="page-psdash">\n    <div class="page-header">\n      <div class="page-title">PS Daily Operations Dashboard</div>\n      <div style="font-size:12px;color:var(--muted);margin-top:4px;">Live from Jira · refreshes every 30 seconds · click any number or ticket to open it in Jira</div>\n    </div>\n    <div class="psd-bar">\n      <button class="btn btn-outline" id="psd-refresh" onclick="psdLoad(true)">↻ Refresh now</button>\n      <label class="psd-chk"><input type="checkbox" id="psd-auto" checked onchange="psdToggleAuto(this.checked)"> Auto-refresh 30s</label>\n      <span class="psd-updated" id="psd-updated">Loading…</span>\n      <span class="psd-spacer"></span>\n      <button class="btn btn-outline" onclick="psdExpand(true)">Expand all</button>\n      <button class="btn btn-outline" onclick="psdExpand(false)">Collapse all</button>\n    </div>\n    <div class="psd-banner" id="psd-banner"></div>\n    <div id="psd-root"></div>\n  </div>\n\n'
PSD_JS = '// ─── PS DASHBOARD (Jira) ──────────────────────────────────────\n// Data comes from GET /api/ps-dashboard (ps_dashboard.py), cached 30s server-side\n// and shared by everyone. Add ?psdemo=1 to the page URL to see sample data.\nconst PSD_API = \'/api/ps-dashboard\';\nconst PSD_REFRESH_MS = 30000;\nconst PSD_MAX_ROWS = 200;\nconst PSD_SECTIONS = [\n  { id: \'action\',     title: \'Action needed\' },\n  { id: \'pending\',    title: \'Pending on others\' },\n  { id: \'monitoring\', title: \'Monitoring\' },\n];\nconst psd = { data: null, timer: null, loading: false, auto: true, open: {}, major: {} };\n\nconst psdEsc = (v) => String(v ?? \'\').replace(/[&<>"\']/g, c => ({ \'&\': \'&amp;\', \'<\': \'&lt;\', \'>\': \'&gt;\', \'"\': \'&quot;\', "\'": \'&#39;\' }[c]));\n\nfunction psdAgeDays(created) {\n  if (!created) return null;\n  const t = Date.parse(String(created).replace(/([+-]\\d{2})(\\d{2})$/, \'$1:$2\'));\n  return isNaN(t) ? null : Math.round((Date.now() - t) / 864e5 * 10) / 10;\n}\nfunction psdTone(f) {\n  if (f.error) return \'err\';\n  if (/blocker/i.test(f.name)) return f.count ? \'red\' : \'ok\';\n  if (/critical/i.test(f.name)) return f.count ? \'amber\' : \'ok\';\n  if (/unassigned/i.test(f.name)) return f.count ? \'amber\' : \'ok\';\n  return \'\';\n}\nfunction psdPrio(p) {\n  const c = /blocker|highest/i.test(p) ? \'red\' : /critical|high/i.test(p) ? \'amber\' : \'\';\n  return `<span class="psd-pr ${c}">${psdEsc(p || \'—\')}</span>`;\n}\nconst psdFilterUrl = (site, id) => `${site}/issues/?filter=${id}`;\n\nfunction psdTile(site, f) {\n  return `<a class="psd-tile ${psdTone(f)}" href="${psdFilterUrl(site, f.id)}" target="_blank" rel="noopener" title="Open filter ${f.id} in Jira">\n    <div class="n">${f.error ? \'—\' : f.count.toLocaleString(\'en-US\')}</div><div class="l">${psdEsc(f.name)}${f.error ? \' · \' + psdEsc(f.error) : \'\'}</div></a>`;\n}\n\nfunction psdTable(site, f) {\n  if (f.error) return `<div class="psd-empty">Could not load this filter (${psdEsc(f.error)}).</div>`;\n  if (!f.issues.length) return `<div class="psd-empty">No tickets.</div>`;\n  const rows = f.issues.map(i => ({ ...i, age: psdAgeDays(i.created) }));\n  rows.sort((a, b) => (b.age ?? -1) - (a.age ?? -1));\n  const shown = rows.slice(0, PSD_MAX_ROWS);\n  const body = shown.map(i => {\n    const cls = i.age == null ? \'\' : i.age >= 14 ? \'old\' : i.age >= 7 ? \'mid\' : \'\';\n    return `<tr><td class="m"><a href="${site}/browse/${psdEsc(i.key)}" target="_blank" rel="noopener">${psdEsc(i.key)}</a></td>\n      <td class="s"><a href="${site}/browse/${psdEsc(i.key)}" target="_blank" rel="noopener" style="color:var(--text)">${psdEsc(i.summary)}</a></td>\n      <td>${psdPrio(i.priority)}</td><td class="n">${psdEsc(i.status)}</td><td class="n">${psdEsc(i.assignee)}</td>\n      <td class="m psd-age ${cls}">${i.age == null ? \'—\' : i.age + \'d\'}</td></tr>`;\n  }).join(\'\');\n  const more = f.count > shown.length\n    ? `<div class="psd-more">Showing ${shown.length} of ${f.count.toLocaleString(\'en-US\')} · <a href="${psdFilterUrl(site, f.id)}" target="_blank" rel="noopener">open all in Jira</a></div>` : \'\';\n  return `<div class="psd-scroll"><table class="psd-t"><thead><tr><th>Key</th><th>Summary</th><th>Priority</th><th>Status</th><th>Assignee</th><th>Age</th></tr></thead><tbody>${body}</tbody></table></div>${more}`;\n}\n\nfunction psdSec(site, f, wide) {\n  const k = \'f\' + f.id;\n  const open = k in psd.open ? psd.open[k] : (!f.error && f.count > 0 && f.count <= 25);\n  return `<details class="psd-sec${wide ? \' wide\' : \'\'}" data-k="${k}"${open ? \' open\' : \'\'}>\n    <summary>${psdEsc(f.name)}<span class="psd-pill"><a href="${psdFilterUrl(site, f.id)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${f.error ? \'!\' : f.count.toLocaleString(\'en-US\')}</a></span></summary>\n    ${psdTable(site, f)}</details>`;\n}\n\n// Owner × priority workload for a set of three priority filters\nfunction psdMatrix(site, title, fs, key) {\n  const cols = fs.map(f => (/blocker/i.test(f.name) ? \'Blocker\' : /critical/i.test(f.name) ? \'Critical\' : \'Normal\'));\n  const by = {};\n  fs.forEach((f, ci) => (f.issues || []).forEach(i => {\n    const o = by[i.assignee] || (by[i.assignee] = [0, 0, 0]);\n    o[ci]++;\n  }));\n  const owners = Object.entries(by).map(([n, c]) => ({ n, c, t: c[0] + c[1] + c[2] })).sort((a, b) => b.t - a.t);\n  const max = owners.length ? owners[0].t : 1;\n  const k = \'m\' + key;\n  const open = k in psd.open ? psd.open[k] : true;\n  const body = owners.map(o => `<tr><td>${psdEsc(o.n)}</td>${o.c.map(v => `<td class="m">${v || \'·\'}</td>`).join(\'\')}\n    <td class="m"><b>${o.t}</b></td><td class="psd-bar-cell"><div class="psd-mini" style="width:${Math.max(3, o.t / max * 100)}%"></div></td></tr>`).join(\'\');\n  return `<details class="psd-sec" data-k="${k}"${open ? \' open\' : \'\'}><summary>${psdEsc(title)}<span class="psd-pill">${owners.reduce((s, o) => s + o.t, 0)}</span></summary>\n    ${owners.length ? `<div class="psd-scroll"><table class="psd-t"><thead><tr><th>Owner</th>${cols.map(c => `<th>${c}</th>`).join(\'\')}<th>Total</th><th></th></tr></thead><tbody>${body}</tbody></table></div>` : \'<div class="psd-empty">No tickets.</div>\'}</details>`;\n}\n\nfunction psdRender() {\n  const d = psd.data;\n  if (!d) return;\n  const site = d.site;\n  const byName = (re) => d.filters.find(f => re.test(f.name));\n  const html = PSD_SECTIONS.map(sec => {\n    const fs = d.filters.filter(f => f.section === sec.id);\n    if (!fs.length) return \'\';\n    const total = fs.filter(f => !/aging|24h|BII/i.test(f.name)).reduce((s, f) => s + (f.count || 0), 0);\n    let extra = \'\';\n    if (sec.id === \'action\') {\n      const pr = fs.filter(f => /^Action –/.test(f.name));\n      extra = psdMatrix(site, \'Owner workload — action\', pr, \'action\');\n    } else if (sec.id === \'pending\') {\n      const pr = fs.filter(f => /^Pending –/.test(f.name));\n      extra = psdMatrix(site, \'Owner workload — pending\', pr, \'pending\');\n    }\n    const lists = [extra].concat(fs.map(f => psdSec(site, f, f.count > 25))).join(\'\');\n    const mk = \'S\' + sec.id;\n    const open = mk in psd.major ? psd.major[mk] : true;\n    return `<details class="psd-major" data-m="${mk}"${open ? \' open\' : \'\'}>\n      <summary>${psdEsc(sec.title)} <span class="psd-total">· ${total.toLocaleString(\'en-US\')} tickets</span></summary>\n      <div class="psd-body"><div class="psd-tiles">${fs.map(f => psdTile(site, f)).join(\'\')}</div>\n      <div class="psd-cols">${lists}</div></div></details>`;\n  }).join(\'\');\n  document.getElementById(\'psd-root\').innerHTML = html;\n  document.getElementById(\'psd-updated\').textContent = \'Updated \' + new Date(d.updated).toLocaleTimeString();\n}\n\nfunction psdBanner(msg) {\n  const b = document.getElementById(\'psd-banner\');\n  b.style.display = msg ? \'block\' : \'none\';\n  b.textContent = msg || \'\';\n}\n\nasync function psdLoad(force) {\n  if (psd.loading) return;\n  psd.loading = true;\n  const btn = document.getElementById(\'psd-refresh\');\n  if (btn) btn.disabled = true;\n  try {\n    if (new URLSearchParams(location.search).has(\'psdemo\')) {\n      psd.data = psdDemo();\n    } else {\n      const resp = await fetch(PSD_API + (force ? \'?refresh=1\' : \'\'), { credentials: \'same-origin\' });\n      if (resp.status === 401) { showLoginScreen(); return; }\n      const j = await resp.json().catch(() => ({}));\n      if (!resp.ok) throw new Error(j.message || (\'HTTP \' + resp.status));\n      psd.data = j;\n    }\n    psdBanner(\'\');\n    psdRender();\n  } catch (e) {\n    psdBanner(\'Could not load Jira data: \' + e.message + (psd.data ? \' — showing the last data received.\' : \'\'));\n    document.getElementById(\'psd-updated\').textContent = \'Update failed\';\n  } finally {\n    psd.loading = false;\n    if (btn) btn.disabled = false;\n  }\n}\n\nfunction psdSchedule() {\n  psdStopSchedule();\n  if (!psd.auto) return;\n  psd.timer = setInterval(() => { if (!document.hidden) psdLoad(false); }, PSD_REFRESH_MS);\n}\nfunction psdStopSchedule() { if (psd.timer) { clearInterval(psd.timer); psd.timer = null; } }\nfunction psdToggleAuto(on) { psd.auto = on; on ? psdSchedule() : psdStopSchedule(); }\n\nfunction psdExpand(open) {\n  document.querySelectorAll(\'#psd-root details\').forEach(el => { el.open = open; });\n  document.querySelectorAll(\'#psd-root details[data-k]\').forEach(el => { psd.open[el.dataset.k] = open; });\n  document.querySelectorAll(\'#psd-root details[data-m]\').forEach(el => { psd.major[el.dataset.m] = open; });\n}\n// Remember what the user opened/closed so a 30s refresh doesn\'t undo it.\ndocument.getElementById(\'psd-root\').addEventListener(\'toggle\', (ev) => {\n  const el = ev.target;\n  if (el.dataset && el.dataset.k) psd.open[el.dataset.k] = el.open;\n  if (el.dataset && el.dataset.m) psd.major[el.dataset.m] = el.open;\n}, true);\n\n// Sample data for ?psdemo=1 (no Jira needed)\nfunction psdDemo() {\n  const now = Date.now(), iso = (d) => new Date(now - d * 864e5).toISOString().replace(\'Z\', \'+0000\');\n  const mk = (n, who, pri, d) => Array.from({ length: n }, (_, i) => ({ key: \'PS-\' + (1000 + i + d), summary: \'Sample ticket \' + (i + 1) + \' for \' + who, priority: pri, status: \'In Progress\', assignee: who, created: iso(d + i) }));\n  const F = (id, name, section, issues) => ({ id, name, section, count: issues.length, issues, error: null });\n  return { site: \'https://bidgely.atlassian.net\', updated: now, filters: [\n    F(34518, \'Unassigned\', \'action\', mk(3, \'Unassigned\', \'Major\', 2)),\n    F(46986, \'Action – Blocker\', \'action\', mk(2, \'Asha\', \'Blocker\', 1)),\n    F(46987, \'Action – Critical\', \'action\', mk(4, \'Ravi\', \'Critical\', 5)),\n    F(46988, \'Action – Normal\', \'action\', mk(9, \'Asha\', \'Medium\', 9)),\n    F(46990, \'BII – Open\', \'action\', mk(2, \'Ravi\', \'Medium\', 3)),\n    F(46984, \'Created in last 24h\', \'action\', mk(3, \'Asha\', \'Medium\', 0)),\n    F(47001, \'Aging queue (all action)\', \'action\', mk(12, \'Ravi\', \'Critical\', 15)),\n    F(46991, \'Pending – Blocker\', \'pending\', []),\n    F(46992, \'Pending – Critical\', \'pending\', mk(2, \'Asha\', \'Critical\', 4)),\n    F(46993, \'Pending – Normal\', \'pending\', mk(30, \'Ravi\', \'Medium\', 6)),\n    F(46994, \'BII – Pending\', \'pending\', mk(1, \'Ravi\', \'Medium\', 6)),\n    F(45225, \'Queue stuck\', \'monitoring\', mk(1, \'Asha\', \'Major\', 1)),\n    F(40966, \'Ingestion gap\', \'monitoring\', []),\n    F(46982, \'HER\', \'monitoring\', mk(2, \'Ravi\', \'Medium\', 3)),\n    F(46983, \'BRE\', \'monitoring\', []),\n    F(45357, \'NISC onboarding\', \'monitoring\', mk(1, \'Asha\', \'Medium\', 8)),\n    F(41065, \'Missing files\', \'monitoring\', mk(5, \'Ravi\', \'Medium\', 2)),\n  ] };\n}\n\n'

ROUTE = """@app.route('/api/ps-dashboard', methods=['GET'])
@login_required
def ps_dashboard_data():
    \"\"\"Live Jira data for the PS Dashboard tab (cached 30s, shared by everyone).\"\"\"
    force = request.args.get('refresh') == '1'
    try:
        return jsonify(ps_dashboard.get_data(force=force))
    except ps_dashboard.NotConfigured as e:
        return jsonify({'status': 'error', 'message': str(e)}), 503
    except Exception as e:
        log.exception('PS dashboard Jira fetch error')
        return jsonify({'status': 'error', 'message': 'Jira request failed'}), 502


"""

def sub_once(text, pattern, repl, label, flags=re.M):
    new, n = re.subn(pattern, repl, text, count=1, flags=flags)
    if n != 1:
        sys.exit('Could not find the place to edit: ' + label + ' (file layout changed?) - nothing was written for it.')
    return new

def patch(path, fn):
    p = ROOT / path
    old = p.read_text()
    new = fn(old)
    if new != old:
        p.write_text(new)
        print('updated  ', path)
    else:
        print('unchanged', path)

(ROOT / 'ps_dashboard.py').write_text(PS_DASHBOARD_PY)
print('wrote     ps_dashboard.py')

def do_server(t):
    if 'ps_dashboard' not in t:
        t = sub_once(t, r'^import sqs_monitor[ \t]*$', 'import sqs_monitor\nimport ps_dashboard', 'import line')
        t = sub_once(t, r'^# ─── HER REVOCATION', lambda m: ROUTE + m.group(0), 'route position')
    return t

def do_index(t):
    if 'page-psdash' in t:
        return t
    t = sub_once(t, r'^  \.page \{ display: none; \}', lambda m: PSD_CSS + m.group(0), 'css')
    t = sub_once(t, r'^  <div class="nav-tab" data-tab="sqsqueues"', lambda m: PSD_NAV + m.group(0), 'nav tab')
    t = sub_once(t, r'^  <div class="page" id="page-sqsqueues">', lambda m: PSD_PAGE + m.group(0), 'page')
    t = sub_once(t, r"^(\s*admin:\s*\{ tabs: \[)'sqsqueues'", r"\1'psdash','sqsqueues'", 'admin role tabs')
    t = sub_once(t, r"^(\s*user:\s*\{ tabs: \[)'sqsqueues'", r"\1'psdash','sqsqueues'", 'user role tabs')
    t = sub_once(t, r"^(\s*delivery:\s*\{ tabs: \[)'rerun'\]", r"\1'psdash','rerun']", 'delivery role tabs')
    t = sub_once(t, r"^(  if \(tab === 'sqsqueues'\) \{[^\n]*\n)", lambda m: m.group(1) + "  if (tab === 'psdash') { psdLoad(); psdSchedule(); } else { psdStopSchedule(); }\n", 'switchTab hook')
    t = sub_once(t, r'^// ─── SQS QUEUES', lambda m: PSD_JS + m.group(0), 'script position')
    return t

def do_secret(t):
    if 'JIRA_EMAIL' in t:
        return t
    return re.sub(r'^(\s*FLASK_SECRET_KEY: "REPLACE_ME")', r'\1\n  JIRA_EMAIL: "REPLACE_ME"      # PS Dashboard tab: Atlassian account email\n  JIRA_TOKEN: "REPLACE_ME"      # PS Dashboard tab: Atlassian API token', t, count=1, flags=re.M)

patch('server.py', do_server)
patch('index.html', do_index)
if (ROOT / 'secret.template.yaml').exists():
    patch('secret.template.yaml', do_secret)

print('\nDone. Next: review with `git diff`, test locally (OPSHUB_LOCAL_NO_AUTH=1 python3 server.py,')
print('open http://localhost:8080/?psdemo=1), then commit and open a PR.')
